try {

  var promobox = document.querySelector('#discount-coupon-form input#coupon_code');


  // Checkout
  if (!promobox) {
    promobox = document.querySelector('#cart-main input#discount-input');
  }

  promobox.dispatchEvent(new Event('input', { bubbles: true })); 
  promobox.dispatchEvent(new Event('focus'));
  promobox.dispatchEvent(new Event('keyup'));
  promobox.dispatchEvent(new Event('blur'));
  promobox.dispatchEvent(new Event('change'));


  //Cart
  if (document.querySelector('#discount-coupon-form input#coupon_code')) {
    document.querySelector('#discount-coupon-form button.action.apply.secondary.small').click(); 
  }
  // Checkout
  else {
    document.querySelector('#cart-main button.discount-field__action.button.button--primary').click(); 
  }


}catch(e) {}

